{
  "summary": "As a married Singaporean couple with no prior flat ownership or housing subsidies, you fall under the first‑timer household rules for purchasing a new HDB flat.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "First‑timer households are defined as Singapore Citizen couples (married, engaged or civil partnership) who have not previously owned any HDB flat or received any HDB housing subsidy."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "Both applicants must be Singapore Citizens; at least one must be at least 21 years old (you meet this requirement)."
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "First‑timer couples are eligible to apply for new BTO projects, resale flats, and some executive condominiums (subject to the 5‑year resale levy rule)."
    },
    {
      "claim_id": "c4",
      "kind": "policy_fact",
      "text": "You may apply for the CPF Housing Grant for first‑timer families, such as the Enhanced CPF Housing Grant (EHG) or the Family Grant, provided you meet the income ceiling and other criteria."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Gather your identification documents (NRICs), recent payslips, CPF statements, and any other documents required for the HFE (Flat Eligibility) application."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Check the upcoming BTO launch schedule on the HDB website and shortlist projects that meet your location and size preferences."
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Specific income ceilings, grant eligibility thresholds, and resale levy rules may change; verify the latest figures on hdb.gov.sg before you apply."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
